head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil71904";
scwin.form = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil71904.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_secugrpId", fn: function(){ return ((dma_readDataVO.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "readDataVO.secugrpId"); })()) ==='TC'); } }, { id: "tr_55", fn: function(){ return ((dma_readDataVO.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "readDataVO.secugrpId"); })()) ==='TC'); } }, { id: "if_secugrpId_2", fn: function(){ return ((dma_readDataVO.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "readDataVO.secugrpId"); })()) ==='IC'); } }, { id: "tr_66", fn: function(){ return ((dma_readDataVO.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "readDataVO.secugrpId"); })()) ==='IC'); } }, { id: "tr_76", fn: function(){ return ((dma_readDataVO.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "readDataVO.secugrpId"); })()) ==='IC'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.init();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71904.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    /* empty */
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「목록보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil71904c.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name __ev_2_btn_Search_onclick
 * @description __ev_2_btn_Search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__ev_2_btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71904.__ev_2_btn_Search_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_DigitalChangePage
 * @description Digital Change Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_DigitalChangePage = async function () {
    const sbmOptions = {
        id: "tx_fn_DigitalChangePage",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_DigitalChangePageReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

